Vue.mixin({
  data: function() {
    return {
        year : this.$localStorage.get("year") ? this.$localStorage.get("year")  :  new Date().getFullYear()  , 
        months : [ 
          { 'name' : 'Jan',  'id' : 'jan'},
          { 'name' : 'Feb',  'id' : 'feb'}, 
          { 'name' : 'Mar', 'id'  : 'mar'}, 
          { 'name' : 'Apr', 'id'  : 'apr'}, 
          { 'name' : 'May', 'id'  : 'may'}, 
          { 'name' : 'Jun', 'id'  : 'jun'},
          { 'name' : 'Jul', 'id'  : 'jul'},
          { 'name' : 'Aug', 'id'  : 'aug'}, 
          { 'name' : 'Sep', 'id'  : 'sep'}, 
          { 'name' : 'Oct', 'id'  : 'oct'}, 
          { 'name' : 'Nov', 'id'  : 'nov'}, 
          { 'name' : 'Dec', 'id'  : 'dec'},
      ],
      quarter_months: [
        {'name' : '1st quarter', 'id'  :  '1'},
        {'name' : '2nd quarter', 'id'  :  '2'},
        {'name' : '3rd quarter', 'id'  :  '3'}, 
        {'name' : '4th quarter','id'  :  '4'},
       
    ],
     format_Date(value){
      return  moment(String(value)).format('YYYY-MM-DD');
     },
      amountConvert(num, digits) {
        var si = [
          { value: 1, symbol: "" },
          { value: 1E3, symbol: "k" },
          { value: 1E6, symbol: "M" },
          { value: 1E9, symbol: "G" },
          { value: 1E12, symbol: "T" },
          { value: 1E15, symbol: "P" },
          { value: 1E18, symbol: "E" }
        ];
        var rx = /\.0+$|(\.[0-9]*[1-9])0+$/;
        var i;
        for (i = si.length - 1; i > 0; i--) {
          if (num >= si[i].value) {
            break;
          }
        }
        return (num / si[i].value).toFixed(digits).replace(rx, "$1") + si[i].symbol;
      },
      getUserType() {
        if (this.$localStorage.get("d_token")) {
          let user = JSON.parse(this.$localStorage.get("user"));
          return user.type;
        }
        return false;
      },
      getReferenceId() {
        if (this.$localStorage.get("d_token")) {
          let user = JSON.parse(this.$localStorage.get("user"));
          return user.reference_id;
        }
        return false;
      },
      permission(e) {
        if (this.$localStorage.get("d_token")) {
          if (e) {
            let user = JSON.parse(this.$localStorage.get("user"));
            let role = user.role_id;
            if (role == 1 && (
              e == "entry_title" || 
              e == "production_menu_title" || 
              e == "products" || 
              e == "cost_center" || 
              e == "factory" || 
              e == "kra_kpi_setting" || 
              e == "summary_group" || 
              e == "costs" || 
              e == "cost_gl" || 
              e == "productionplans" || 
              e == "production_targets" || 
              e == "standard_cost" || 
              e == "factory_capacity" || 
              e == "production_wastage_daft" || 
              e == "manufacture_report" || 
              e == "department" || 
              e == "operation_menu_title" || 
              e == "users" || 
              e == "kra_kpi_mos"||
              e == "entry_title"||
              e == "work_schedule_menu" || 
              e == "daily_work" ||   
              e == "kra_kpi_mos_list" || 
              e == "wings" || 
              e == "weightage_list" || 
              e == "report_menu_title" || 
              e == "bpt_report" || 
              e == "monthly_report"  
               )) {
              // System administrator
              return true;
            } else if (role == 2 && ( e == "department" || e == "column_dept"  )) {
              // MD's Office
              return true;
            } else if ( role == 3 &&
              (e == "department" ||
               e == "production_menu_title" ||
               e == "products" ||
               e == "column_dept"  )) {
              //DMD's Office
              return true; 
            } else if ( role == 4 &&( 
              e == "monthly_budget_list"  || 
              e == "production_menu_title" ||
              e == "products"
              )) {
              // Cost center
              return true;
            } else if (role == 5 &&
              (e == "entry_title"||
               e == "work_schedule_menu" || 
               e == "daily_work" || 
               e == "add_daily_work" || 
               e == "kra_kpi_mos" || 
               e == "kra_kpi_mos_list" || 
               e == "wings" || 
               e == "weightage_list" || 
               e == "report_menu_title" || 
               e == "bpt_report" || 
               e == "monthly_report" || 
               e == "users" || 
               e == "operation_menu_title" || 
               e == "kra_kpi_setting" )) {
                  // HOD
               return true;
            } else if (
              role == 6 &&
              ( e == "bpt_report" || 
                e == "bpt_report" ||
                e == "work_schedule_menu" || 
                e == "daily_work" || 
                e == "add_daily_work" || 
                e == "expenses"  )
            ) { 
              //Wings
              return true;
            }else if(
              role == 7 &&
              ( e == "work_schedule_menu" || 
                e == "daily_work" || 
                e == "add_daily_work"   )){
              return true;
            } else{
              return false;
            }
          } else {
            return false;
          }
        } else {
          return false;
        }
      },
      formatPrice(val) { 
        val = val.toFixed(0);
        return val.toString().replace(/(\d)(?=(\d\d\d)+(?!\d))/g, "$1,")  ;


      },
      async getMonth() {
        return await axios.get(this.api_url + "months", {
          headers: {
            "Content-Type": "application/json",
            Authorization: this.$localStorage.get("d_token")
              ? `Bearer ${this.$localStorage.get("d_token")}`
              : "",
          },
        });
      },
     
   
      async getDepartments(  status = null) {
        let where = "?";
     
        if (status) {
          where += "status=" + status;
        }
        return await axios.get(this.api_url + "departments" + where, {
          headers: {
            "Content-Type": "application/json",
            Authorization: this.$localStorage.get("d_token")
              ? `Bearer ${this.$localStorage.get("d_token")}`
              : "",
          },
        });
      },
      
     
      async getItem(url) {
        return await axios.get(this.api_url + url, {
          headers: {
            "Content-Type": "application/json",
            Authorization: this.$localStorage.get("d_token")
              ? `Bearer ${this.$localStorage.get("d_token")}`
              : "",
          },
        });
      },
    };
  }
})
