    <script>
    import axios from "../../axios_instance";
    export default {
        props: {},
        components: {
            // VueRecaptcha, facebookLogin
        },
        data() {
            return {
                base_url: window.base_url,
                api_url: window.api_url,
                token: this.$localStorage.get("d_token"),
                items: [],   
                status: '',
            };
        },
        created() { 
            this.getItems(); 
        },
        methods: {
            achievement(item , month){
                if(item.mostargetjoin ? item.mostargetjoin[month] : 0 > 0  && item.mosachievementjoin ? item.mosachievementjoin[month]  : 0 > 0 ){
                    return  ((item.mostargetjoin ? item.mostargetjoin[month] : 0 / item.mosachievementjoin ? item.mosachievementjoin[month] : 0) * 100).toFixed()  ;
                }else{
                    return  0 ;
                }
               // (item.mostargetjoin.january / item.mosachievementjoin.january)/100

            },
            checkConditionKra( length , kpi_index , mos_index  ){ 
                if(kpi_index == 0 &&  mos_index == 0 ){
                    return  true ;
                }else{
                    return  false ;
                } 
            },
            checkConditionKpi( length  , mos_index  ){ 
                if(mos_index == 0 ){
                    return  true ;
                }else{
                    return  false ;
                } 
            },
            async getItems() {
                let where = '?'; 
          
                // if (this.status) {
                //     where += '&status=' + this.status;
                // }
                let loader = this.$loading.show();
                try {
                    await axios
                        .get(this.api_url + "kra_kpi_mos_list" + where, {
                            headers: {
                                "Content-Type": "application/json",
                                Authorization: this.token ? `Bearer ${this.token}` : ""
                            },
                        })
                        .then(({
                            data
                        }) => {
                            if (data.success) {
                                this.items = data.data ;
                                console.log( this.items );
                            }
                            loader.hide();
                        });
                } catch (error) {
                    loader.hide();
                }
            },
        
        },
