<template>
    <div>
        <div class="app-content content"> 
        <div class="content-wrapper">
            <div class="content-header row">
                <div class="content-header-left col-12 mb-1 mt-0">
                    <div class="row breadcrumbs-top">
                        <div class="col-12"> 
                            <div class="breadcrumb-wrapper col-12">
                                <ol class="breadcrumb p-0 mb-0">
                                     <li class="breadcrumb-item"><router-link :to="{ path: '/' }"><i class="bx bx-home-alt"></i></router-link>
                                    </li>
                                    <li class="breadcrumb-item  "> <router-link :to="{ path: '/daily_work' }"> Daily Work </router-link>
                                    </li>
                                    <li class="breadcrumb-item active"> Add Task 
                                    </li>
                                    
                                </ol>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
            <div class="content-body">  
                <section class="input-validation">
                    <div class="row">
                        <div class="col-md-12">
                            <div class="card">
                                <div class="card-header">
                                    <h4 class="card-title">Add daily work</h4>
                                </div>
                                <div class="card-content">
                                    <div class="card-body">
                                        <form @submit.prevent="create()">
                                                <div class="row"> 
                                                    <div class="col-md-4"> 
                                                        <div class="form-group">
                                                            <label for="Profession">Date</label>
                                                            <div class="controls">
                                                                <datepicker v-model="addForm.date" name="date" class="form-control"  ></datepicker>
                                                                <!-- <input type="text" name="date" v-model="addForm.date" :class="{  'is-invalid': addForm.errors.has('date'),  }" class="form-control" data-validation-required-message="This field is required" placeholder="Date"> -->
                                                            </div>
                                                        </div> 
                                                    </div> 
                                                    <div class="col-md-3"> 
                                                        <div class="form-group">
                                                            <label for="Profession">Start Time</label>
                                                            <div class="controls">
                                                                <input type="text" name="start_time" v-model="addForm.start_time" :class="{  'is-invalid': addForm.errors.has('start_time'),  }" class="form-control" data-validation-required-message="This field is required" placeholder="Start Time">
                                                            </div>
                                                        </div> 
                                                    </div> 
                                                    <div class="col-md-4"> 
                                                        <div class="form-group">
                                                            <label for="Profession">End Time</label>
                                                            <div class="controls">
                                                                <input type="text" name="name" v-model="addForm.end_time" :class="{  'is-invalid': addForm.errors.has('end_time'),  }" class="form-control" data-validation-required-message="This field is required" placeholder="End Time">
                                                            </div>
                                                        </div> 
                                                    </div> 
                                                </div>
                                                <div class="row"> 
                                                    <div class="col-md-4"> 
                                                        <div class="form-group">
                                                            <label for="Profession">KRA</label>
                                                            <div class="controls">
                                                                <select  id="Profession" name="kra_id"  @change="getKpi()"  v-model="addForm.kra_id" :class="{  'is-invalid': addForm.errors.has('kra_id'),  }" class="form-control">
                                                                    <option value="">Select one</option>
                                                                    <option  v-for="row in kraItem" :key="row.id" :value="row.id">{{ row.kra_name}}</option>  
                                                                </select>
                                                            </div>
                                                        </div> 
                                                    </div> 
                                                    <div class="col-md-3"> 
                                                        <div class="form-group">
                                                            <label for="Profession">KPI</label>
                                                            <div class="controls">
                                                                <select  id="Profession" name="kpi_id" @change="getMos()"   v-model="addForm.kpi_id" :class="{  'is-invalid': addForm.errors.has('kpi_id'),  }" class="form-control">
                                                                    <option value="">Select one</option>
                                                                    <option  v-for="row in kpiItem" :key="row.id" :value="row.id">{{ row.kpi_name}}</option>  
                                                                </select>
                                                            </div>
                                                        </div> 
                                                    </div> 
                                                    <div class="col-md-4"> 
                                                        <div class="form-group">
                                                            <label for="Profession">MOS</label>
                                                            <div class="controls">
                                                                <select  id="Profession" name="mos_id"    v-model="addForm.mos_id" :class="{  'is-invalid': addForm.errors.has('mos_id'),  }" class="form-control">
                                                                    <option value="">Select one</option>
                                                                    <option  v-for="row in mosItem" :key="row.id" :value="row.id">{{ row.mos_name}}</option>  
                                                                </select>
                                                            </div>
                                                        </div> 
                                                    </div> 
                                                </div>
                                                <div class="row"> 
                                                    <div class="col-md-11"> 
                                                        <div class="form-group">
                                                            <label>Work Details</label>
                                                            <div class="controls">
                                                                <vue-editor name="task" v-model="addForm.task" :class="{  'is-invalid': addForm.errors.has('task'),  }" ></vue-editor>
                                                                <!-- //<textarea name="task" v-model="addForm.task" :class="{  'is-invalid': addForm.errors.has('task'),  }" class="form-control" data-validation-required-message="This field is required" placeholder="Work Task"></textarea> -->
                                                            </div>
                                                        </div>
                                                    </div>
                                                </div>   
                                            <button type="submit" class="btn btn-primary">Submit</button>
                                        </form>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                </section>
                <!-- Input Validation end -->
            </div>
        </div>
    </div>
    </div> 
</template>
<script>
import axios from "../../axios_instance"; 
import { Form } from "vform"; 
import Datepicker from 'vuejs-datepicker';
import { VueEditor } from "vue2-editor";
export default {
  props: { 
  },
  components: {
    Datepicker,
    VueEditor
    // VueRecaptcha, facebookLogin 
  },
  data() {
    return {
        base_url: window.base_url,
        api_url: window.api_url,    
        DepartmentsItems : [],
        token: this.$localStorage.get("d_token"), 
        addForm: new Form({ 
            task: "",     
            dept_id : "",  
            kra_id : "",
            kpi_id : "",
            mos_id : "",
            date    : new Date() ,
            start_time : "09:30:00",
            end_time : "81:30:00",
            user_id : 1,

        }),
        kraItem: [] ,  
        kpiItem: [] ,  
        mosItem: [] ,  
    };
  },
  created() {
      
    this.getKRA()
    this.dept();
  },
  methods: { 
    create(){ 
      try {
        let loader = this.$loading.show();
        this.addForm.post(this.api_url + "daily_schedules", {
            headers: {
              "Content-Type": "application/json", 
              Authorization: this.token ? `Bearer ${this.token}` : ""
            },
          }).then((res) => {
              console.log(res);
              if(res.data.success){
                this.$toasted.show(res.data.message, {
                    theme: "bubble",
                    duration: 5000,
                    position: "bottom-right",
                });
              } 
            loader.hide();  
            this.$router.push('/daily_work');
        },(error)=>{
          console.log(error);
           loader.hide(); 
        })
      } catch (error) {
         // loader.hide(); 
        console.log(error);
      }
    },
    async dept() {
      this.getDepartments().then(({ data }) => {
        if (data.success) {
          this.DepartmentsItems = data.data;
        }
      });
    }, 

async  getKRA(){   
    await axios.get(this.api_url + "k_r_a_s", {
            headers: {
            "Content-Type": "application/json", 
            Authorization: this.token ? `Bearer ${this.token}` : ""
            },
        })
    .then(({ data }) => {  
        this.kraItem =  data.data ;
        console.log(this.kraItem );   
    });
},
async getKpi(){ 
    console.log(this.addForm.kra_id);
    await axios.get(this.api_url + "k_p_i_s?kra_id="+this.addForm.kra_id, {
                headers: {
                "Content-Type": "application/json", 
                Authorization: this.token ? `Bearer ${this.token}` : ""
                },
            })
    .then(({ data }) => {  
            this.kpiItem =  data.data ;
            console.log(this.roles );   
    });
}, 
async getMos(){ 
    await axios.get(this.api_url + "m_o_s?kpi_id="+this.addForm.kpi_id, {
        headers: {
        "Content-Type": "application/json", 
        Authorization: this.token ? `Bearer ${this.token}` : ""
        },
    })
    .then(({ data }) => {  
        this.mosItem =  data.data ;
        console.log(this.roles );   
    });
} ,
 async getRole(){ 
        await axios.get(this.api_url + "role", {
                headers: {
                "Content-Type": "application/json", 
                Authorization: this.token ? `Bearer ${this.token}` : ""
                },
            })
        .then(({ data }) => {  
            this.roles =  data.data ;
            console.log(this.roles );   
        }); 
    },
  },
  computed: {},
};
</script>
