<template>
    <div>
        <div class="app-content content">
            <div class="content-wrapper">
                <div class="content-header row">
                    <div class="content-header-left col-12 mb-1 mt-0">
                        <div class="row breadcrumbs-top">
                            <div class="col-sm-9">
                                <div class="breadcrumb-wrapper col-9">
                                    <ol class="breadcrumb p-0 mb-0">
                                        <li class="breadcrumb-item">
                                            <router-link :to="{ path: '/' }"><i class="bx bx-home-alt"></i></router-link>
                                        </li>
                                        <li class="breadcrumb-item active"> KRA , KPI and MOS 
                                        </li>
                                    </ol>
                                </div>
                            </div>
                            <div class=" col-sm-3">
                                <!-- <router-link class="btn btn-primary add-btn" :to="{ path: '/add_daily_work' }"> <i class="bx bx-add-alt"></i> Add daily work </router-link> -->
                            </div>
                        </div>
                    </div>
                </div>
                <div class="content-body">
                    <section id="basic-datatable">
                        <div  class="users-list-filter px-1"> 
                            <div class="row border rounded py-2 mb-2">
                               <div v-if="role_id == 1 || role_id == 2 || role_id == 3 || role_id == 4 " class="col-12 col-sm-6 col-lg-2">
                                  <label for="users-list-verified">Department</label>
                                  <fieldset class="form-group">
                                     <select class="form-control" v-on:change="getItems()" v-model="filterForm.dept_id"  id="users-list-verified" >
                                         <option value="">Select One</option>
                                         <option v-for="row in deptItems" :key="row.id" :value="row.id" >
                                         {{ row.name }}
                                         </option>
                                     </select> 
                                  </fieldset>
                               </div> 
                            </div>
                      </div>
                        <div class="row">
                            <div class="col-12">
                                <div class="card">
                                    <div class="card-content">
                                        <div class="card-body card-dashboard"> 
                                            <div class="table-responsive">  
                                                <table class="table table-bordered table-sm">
                                                    <thead class="thead-dark"> 
                                                    <tr> 
                                                        <th>KRA</th>
                                                        <th>Weightage</th>
                                                        <th>KPI</th>
                                                        <th>MOS</th> 
                                                        <th>Jan</th>
                                                        <th>Feb</th>
                                                        <th>Mar</th>
                                                        <th>Apr</th>
                                                        <th>May</th>
                                                        <th>Jun</th>
                                                        <th>Jul</th>
                                                        <th>Aug</th>
                                                        <th>Sep</th>
                                                        <th>Oct</th>
                                                        <th>Nov</th>
                                                        <th>Dec</th>
                                                        <th v-if="role_id == 5">Action</th>
                                                    </tr>
                                                    </thead>
                                                    <tbody>
                                                        <template v-for="(item , index ) in items" >  
                                                             
                                                            <tr  :key="item.id" >   
                                                                <td :rowspan="item.kra_count" v-if="items[index > 0 ? index - 1 : 0 ].kra_id != item.kra_id || index ==0" >{{ item.krajoin ? item.krajoin.kra_name : '' }}</td>
                                                                <td :rowspan="item.kra_count" v-if="items[index > 0 ? index - 1 : 0 ].kra_id != item.kra_id || index ==0" >{{ item.krajoin ? item.krajoin.kra_weight : '' }}</td>
                                                                <td :rowspan="item.kpi_count" v-if="items[index > 0 ? index - 1 : 0 ].kpi_id != item.kpi_id || index ==0" >{{ item.kpijoin ? item.kpijoin.kpi_name : '' }}</td>
                                                                <td>{{ item.mos_name }}</td>
                                                                <td><i v-if="item.mostargetjoin ? item.mostargetjoin.january : 0 > 0" class="bx bx-map"></i> </td>
                                                                <td><i v-if="item.mostargetjoin ? item.mostargetjoin.february : 0 > 0" class="bx bx-map"></i> </td>
                                                                <td><i v-if="item.mostargetjoin ? item.mostargetjoin.march : 0 > 0" class="bx bx-map"></i> </td>
                                                                <td><i v-if="item.mostargetjoin ? item.mostargetjoin.april : 0 > 0" class="bx bx-map"></i> </td>
                                                                <td><i v-if="item.mostargetjoin ? item.mostargetjoin.may : 0 > 0" class="bx bx-map"></i> </td>
                                                                <td><i v-if="item.mostargetjoin ? item.mostargetjoin.june : 0 > 0" class="bx bx-map"></i> </td>
                                                                <td><i v-if="item.mostargetjoin ? item.mostargetjoin.july : 0 > 0" class="bx bx-map"></i> </td>
                                                                <td><i v-if="item.mostargetjoin ? item.mostargetjoin.august : 0 > 0" class="bx bx-map"></i> </td>
                                                                <td><i v-if="item.mostargetjoin ? item.mostargetjoin.september : 0 > 0" class="bx bx-map"></i> </td>
                                                                <td><i v-if="item.mostargetjoin ? item.mostargetjoin.october : 0 > 0" class="bx bx-map"></i> </td>
                                                                <td><i v-if="item.mostargetjoin ? item.mostargetjoin.november : 0 > 0" class="bx bx-map"></i> </td>
                                                                <td><i v-if="item.mostargetjoin ? item.mostargetjoin.december : 0 > 0" class="bx bx-map"></i> </td>
                                                                <td v-if="role_id == 5"> 
                                                                    <button class="btn btn-success btn-sm" > Add || Edit KPI  </button>
                                                                    <router-link class="btn btn-primary add-btn" :to="{ path: '/measure_of_success/'+ item.kpi_id }"> <i class="bx bx-add-alt"></i>MOS  </router-link> 
                                                                    <a class="btn btn-primary btn-sm" href="https://bpt.ssgbd.com/value_fwr/125/378">FWR</a> 
                                                                </td> 
                                                            </tr> 
                                                                 
                                                        </template> 
                                                    </tbody>
                                                </table> 
 
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </section>
                </div>
            </div>
        </div>
    </div>
    </template>
    
    <script>
    import axios from "../../axios_instance";
    import { Form } from "vform"; 
    export default {
        props: {},
        components: {
            // VueRecaptcha, facebookLogin
        },
        data() {
            return {
                base_url: window.base_url,
                api_url: window.api_url,
                token: this.$localStorage.get("d_token"),
                user_data: JSON.parse(this.$localStorage.get("user")),
                role_id : '',
                items: [],  
                deptItems : [],  
                filterForm: new Form({ 
                    dept_id: "", 
                }),
                status: '',
            };
        },
        created() { 
            this.role_id = this.user_data.role_id ;  
            if(this.role_id == 1 || this.role_id == 2 || this.role_id == 3 || this.role_id == 4 ){
                this.getDept();
            }else{
                //this.getItems(); 
                this.filterForm.dept_id = this.user_data.dept_id ;
                this.getItems(); 
            }
           // this.getItems(); 
        },
        methods: {
            checkConditionKra( length , kpi_index , mos_index  ){ 
                if(kpi_index == 0 &&  mos_index == 0 ){
                    return  true ;
                }else{
                    return  false ;
                } 
            },
            checkConditionKpi( length  , mos_index  ){ 
                if(mos_index == 0 ){
                    return  true ;
                }else{
                    return  false ;
                } 
            },
            async getItems() {
                if(this.filterForm.dept_id !=''){
                    let where = ''; 
                    if (this.filterForm.dept_id) {
                        where += '?dept_id=' + this.filterForm.dept_id;
                    }
                    let loader = this.$loading.show();
                    try {
                        await axios
                            .get(this.api_url + "kra_kpi_mos_list" + where, {
                                headers: {
                                    "Content-Type": "application/json",
                                    Authorization: this.token ? `Bearer ${this.token}` : ""
                                },
                            })
                            .then(({
                                data
                            }) => {
                                if (data.success) {
                                    this.items = data.data ;
                                    console.log( this.items );
                                }
                                loader.hide();
                            });
                    } catch (error) {
                        loader.hide();
                    }
                }
            },

            async getDept(){
                let loader = this.$loading.show();
                this.getDepartments( this.status ).then(({ data }) => { 
                    if(data.success){
                        loader.hide();
                        this.deptItems =  data.data ;
                        //this.getItems(); 
                    }else{
                        loader.hide(); 
                    }
                }); 
            },
        
        },
        computed: {},
    };
    </script>
    